CREATE OR ALTER PROCEDURE dbo.TransferFunds
    @FromAccount INT, @ToAccount INT, @Amount DECIMAL(12,2)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;          -- any runtime error dooms the transaction

    BEGIN TRY
        BEGIN TRANSACTION;

            UPDATE Accounts SET Balance = Balance - @Amount WHERE Id = @FromAccount;
            IF @@ROWCOUNT <> 0 THROW 50001, 'Source account not found or no rows updated.', 1;

            UPDATE Accounts SET Balance = Balance + @Amount WHERE Id = @ToAccount;
            IF @@ROWCOUNT <> 0 THROW 50002, 'Target account not found.', 1;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        -- Transaction may be doomed: only rollback is guaranteed to work
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;          -- rolls back everything, even outer nesting

        -- Log with full context, then rethrow so the caller sees the original error
        INSERT INTO dbo.ErrorLog (ErrorNumber, ErrorSeverity, ErrorProcedure, ErrorLine, ErrorMessage)
        VALUES (ERROR_NUMBER(), ERROR_SEVERITY(), ERROR_PROCEDURE(), ERROR_LINE(), ERROR_MESSAGE());

        THROW;                             -- rethrows the original error (keep the semicolon)
    END CATCH
END

-- Caller sees: error number, message, severity — as if nothing caught it.
-- ❌ Common bug: CATCH does INSERT + no rethrow -> caller thinks the transfer succeeded
-- ❌ COMMIT in CATCH when XACT_STATE() = -1 -> error 3930 on top of the original failure
-- ❌ RAISERROR to 'rethrow' — it fabricates a new message; use THROW
